private lazy var exteraCameraBarButton = UIBarButtonItem(image: UIImage(systemName: "camera"), style: .plain, target: self, action: #selector(self.exteraCameraPressed))

private var exteraUsesSeparateCameraButton: Bool {
    guard case .assets(nil, .default) = self.subject else { return false }
    return ExteraPreferences.standard.value(for: ExteraSettings.hideCameraTile)
}

private var exteraCameraButtonVisible: Bool {
    return self.exteraUsesSeparateCameraButton && self.selectionCount == 0
        && self.controllerNode.currentDisplayMode == .all
        && (self.bannedSendPhotos == nil || self.bannedSendVideos == nil)
        && self.openCamera != nil && UIImagePickerController.isSourceTypeAvailable(.camera)
}

@objc private func exteraCameraPressed() {
    guard self.exteraCameraButtonVisible else { return }
    self.view.endEditing(true)
    self.openCamera?(nil)
}

@objc private func rightButtonPressed() {

var rightControlItems: [GlassControlGroupComponent.Item] = []
if self.exteraCameraButtonVisible, case .glass = self.style {
    rightControlItems.append(GlassControlGroupComponent.Item(
        id: AnyHashable("exteraCamera"),
        content: .icon("Chat/Attach Menu/OpenCamera"),
        action: { [weak self] in self?.exteraCameraPressed() }
    ))
}
if case .glass = self.style {
} else if self.exteraUsesSeparateCameraButton {
    if self.exteraCameraButtonVisible {
        self.exteraCameraBarButton.accessibilityLabel = self.presentationData.strings.Attachment_OpenCamera
        if self.navigationItem.rightBarButtonItem !== self.exteraCameraBarButton {
            self.navigationItem.rightBarButtonItem = self.exteraCameraBarButton
        }
    } else if self.navigationItem.rightBarButtonItem === self.exteraCameraBarButton {
        if self.bannedSendPhotos != nil && self.bannedSendVideos != nil {
            self.navigationItem.rightBarButtonItem = nil
        } else {
            self.navigationItem.rightBarButtonItem = UIBarButtonItem(customDisplayNode: self.moreButtonNode)
            self.navigationItem.rightBarButtonItem?.action = #selector(self.rightButtonPressed)
            self.navigationItem.rightBarButtonItem?.target = self
        }
    }
}

